    "roleDatePalmFarmer": "ਕਿਸਾਨ, ਗੁਜਰਾਤ",
    "testimonial2Text": "ਬੀਮਾਰੀ ਦੀ ਪਛਾਣ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾ ਨੇ ਮੇਰੀਆਂ ਫ਼ਸਲਾਂ 'ਤੇ ਬੀਮਾਰੀ ਨੂੰ ਜਲਦੀ ਫੜ ਲਿਆ। ਮੇਰੀ ਪੂਰੀ ਫ਼ਸਲ ਬਚ ਗਈ!",
    "faqHeader": "ਅਕਸਰ ਪੁੱਛੇ ਜਾਂਦੇ ਸਵਾਲ",
    "faq1Q": "ਏਆਈ ਮਿੱਟੀ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਿੰਨਾ ਸਟੀਕ ਹੈ?",
    "faq1A": "ਸਾਡੇ ਮਸ਼ੀਨ ਲਰਨਿੰਗ ਮਾਡਲ 500,000 ਤੋਂ ਵੱਧ ਮਿੱਟੀ ਦੇ ਨਮੂਨਿਆਂ 'ਤੇ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਹਨ ਅਤੇ NPK ਅਤੇ ਮਿੱਟੀ ਦੀ ਕਿਸਮ ਦੇ ਵਰਗੀਕਰਨ ਵਿੱਚ 98.2% ਤੋਂ ਵੱਧ ਸਟੀਕਤਾ ਪ੍ਰਾਪਤ ਕਰਦੇ ਹਨ।",
    "faq2Q": "ਕੀ ਇਹ ਖੇਤਰੀ ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ?",
    "faq2A": "ਹਾਂ! ਐਗਰੋ AI ਹਿੰਦੀ, ਤੇਲਗੂ, ਤਾਮਿਲ, ਕੰਨੜ, ਮਲਿਆਲਮ, ਮਰਾਠੀ, ਬੰਗਾਲੀ, ਗੁਜਰਾਤੀ, ਪੰਜਾਬੀ, ਉੜੀਆ ਅਤੇ ਅਸਾਮੀ ਸਮੇਤ 23+ ਭਾਰਤੀ ਖੇਤਰੀ ਭਾਸ਼ਾਵਾਂ ਦਾ ਸਮਰਥਨ ਕਰਦਾ ਹੈ।",
    "faq3Q": "ਕੀ ਮੈਂ ਵਿਸ਼ੇਸ਼ ਹਾਰਡਵੇਅਰ ਤੋਂ ਬਿਨਾਂ ਐਗਰੋ AI ਦੀ ਵਰਤੋਂ ਕਰ ਸਕਦਾ ਹਾਂ?",
    "faq3A": "ਹਾਂ! ਤੁਸੀਂ ਮਿੱਟੀ ਦੀ ਤਸਵੀਰ ਖਿੱਚਣ ਲਈ ਕਿਸੇ ਵੀ ਸਮਾਰਟਫ਼ੋਨ ਕੈਮਰੇ ਦੀ ਵਰਤੋਂ ਕਰ ਸਕਦੇ ਹੋ, ਜਾਂ ਸਾਧਾਰਨ ਵੈੱਬ ਫਾਰਮ ਵਿੱਚ ਆਪਣੇ ਮਿੱਟੀ ਦੇ ਟੈਸਟ ਦੇ ਮੁੱਲ ਖੁਦ ਟਾਈਪ ਕਰ ਸਕਦੇ ਹੋ।",
    "readyTransformFarm": "ਆਪਣੀ ਖੇਤੀ ਨੂੰ ਬਦਲਣ ਲਈ ਤਿਆਰ ਹੋ?",
