    "roleWheatFarmer": "ଗହମ କୃଷକ, ପଞ୍ଜାବ",
    "testimonial1Text": "ଏଗ୍ରୋ AI ମୋର ମୃତ୍ତିକା pH ପାଇଁ ସର୍ବୋତ୍ତମ ଫସଲ ବାଛିବାରେ ସାହାଯ୍ୟ କଲା । ଏହି ଋତୁରେ ମୋର ଅମଳ 25% ବୃଦ୍ଧି ପାଇଛି!",
    "roleDatePalmFarmer": "କୃଷକ, ଗୁଜରାଟ",
    "testimonial2Text": "ରୋଗ ଚିହ୍ନଟ ସୁବିଧା ମୋର ଫସଲରେ ରୋଗ ଶୀଘ୍ର ଧରିପାରିଲା । ମୋର ସମ୍ପୂର୍ଣ୍ଣ ଅମଳ ରକ୍ଷା ପାଇଗଲା!",
    "faqHeader": "ବାରମ୍ବାର ପଚରାଯାଉଥିବା ପ୍ରଶ୍ନ",
    "faq1Q": "AI ମୃତ୍ତିକା ବିଶ୍ଳେଷଣ କେତେ ସଠିକ୍?",
    "faq1A": "ଆମର ମେସିନ୍ ଲର୍ନିଂ ମଡେଲ୍ 500,000 ରୁ ଅଧିକ ମୃତ୍ତିକା ନମୁନାରେ ପ୍ରଶିକ୍ଷିତ ଏବଂ NPK ଏବଂ ମୃତ୍ତିକା ପ୍ରକାର ବର୍ଗୀକରଣରେ 98.2% ରୁ ଅଧିକ ସଠିକତା ହାସଲ କରେ ।",
    "faq2Q": "ଏହା ଆଞ୍ଚଳିକ ଭାରତୀୟ ଭାଷାକୁ ସମର୍ଥନ କରେ କି?",
    "faq2A": "ହଁ! ଏଗ୍ରୋ AI ହିନ୍ଦୀ, ତେଲୁଗୁ, ତାମିଲ, କନ୍ନଡ, ମଲାୟାଲମ୍, ମରାଠୀ, ବଙ୍ଗାଳୀ, ଗୁଜରାଟୀ, ପଞ୍ଜାବୀ, ଓଡ଼ିଆ ଏବଂ ଅସମୀୟା ସହିତ 23+ ଭାରତୀୟ ଭାଷାକୁ ସମର୍ଥନ କରେ ।",
    "faq3Q": "ମୁଁ କୌଣସି ସ୍ୱତନ୍ତ୍ର ହାର୍ଡୱେର୍ ବିନା ଏଗ୍ରୋ AI ବ୍ୟବହାର କରିପାରିବି କି?",
